class MainActivity:Activity(){private lateinit var store:EventStore;private lateinit var timeline:TimelineView;private val ui=Handler(Looper.getMainLooper());private val savePending=Runnable{saveStateNow()};private val nowRefresh=object:Runnable{override fun run(){if(::timeline.isInitialized){timeline.invalidate();ui.postDelayed(this,250L)}}};private lateinit var scaleText:TextView;private var outgoing:List<TimelineEvent>?=null;private var gpsCallback:((String,String,String)->Unit)?=null;private var lastLocationStatus="No GPS request";private var activeListener:LocationListener?=null;private var listenerTimeout:Runnable?=null;override fun onCreate(state:Bundle?){super.onCreate(state);window.statusBarColor=BLACK;window.navigationBarColor=BLACK;window.decorView.systemUiVisibility=0;store=EventStore(this);val prefs=getSharedPreferences("viewport",MODE_PRIVATE);val root=column();val toolbar=row();val name=label("DEEP TIMELINE",16f);toolbar.add(name,0,dp(52),1f);name.setOnLongClickListener{timeline.resetHorizontal();true};name.contentDescription="Search all timeline events";name.setOnClickListener{openEventSearch()};val now=Glyph(this,"now");toolbar.add(now,dp(46),dp(52));now.setOnClickListener{timeline.jumpNow()};now.setOnLongClickListener{observerSettings();true};val scaleBox=column();scaleBox.gravity=Gravity.CENTER;val scale=Glyph(this,"scale");scaleBox.add(scale,dp(42),dp(36));scaleText=label("DAY",9f).apply{gravity=Gravity.CENTER;setPadding(0,0,0,0)};scaleBox.add(scaleText,-1,dp(14));toolbar.add(scaleBox,dp(52),dp(52));scale.setOnClickListener{timeline.setPreset(timeline.selectedScale);updateScaleLabel()};scale.setOnLongClickListener{choose("REFERENCE INTERVAL",listOf("DAY — 86,400 seconds","MEAN SYNODIC MONTH","MEAN DECEMBER-SOLSTICE YEAR")){i->timeline.setPreset(i);updateScaleLabel()};true};scaleBox.setOnClickListener{timeline.setPreset(timeline.selectedScale);updateScaleLabel()};scaleBox.setOnLongClickListener{choose("REFERENCE INTERVAL",listOf("DAY — 86,400 seconds","MEAN SYNODIC MONTH","MEAN DECEMBER-SOLSTICE YEAR")){i->timeline.setPreset(i);updateScaleLabel()};true};val plus=Glyph(this,"plus");toolbar.add(plus,dp(48),dp(52));plus.setOnClickListener{EventEditor(this,null).show()};val transfer=Glyph(this,"transfer");toolbar.add(transfer,dp(45),dp(52));transfer.contentDescription="Import ICS or JSON and export JSON events";transfer.setOnClickListener{choose("EVENT DATA",listOf("IMPORT JSON","IMPORT ICS","EXPORT EVENTS JSON","EXPORT JSON TEMPLATE","DANGER ZONE","SET EVENT VISIBILITY LIMITS","SEARCH ALL EVENTS")){when(it){0->openImport();1->openIcsImport();2->TransferSelection(this,store.all().mapIndexed{index,event->TransferEntry(index,event.title,event.civil,event,"READY",true)},false){selected->outgoing=selected;saveDocument(false)}.show();3->saveDocument(true);4->openDangerZone();5->openBulkVisibility();6->openEventSearch()}}};val info=Glyph(this,"info");toolbar.add(info,dp(42),dp(52));info.setOnClickListener{diagnostics()};root.add(toolbar);timeline=TimelineView(this);timeline.center=try{Moment(prefs.getLong("center_second",Instant.now().epochSecond),prefs.getInt("center_nano",0))}catch(_:Exception){Moment.now()};timeline.selectedScale=prefs.getInt("scale",0).coerceIn(0,2);if(prefs.contains("spp")){val value=prefs.getString("spp","")?.toDoubleOrNull();if(value!=null&&value.isFinite()&&value>0.0){timeline.secondsPerPixel=value;timeline.initialized=true}};timeline.horizontalPan=prefs.getFloat("horizontal",0f);timeline.setAll(store.all());timeline.observerLongitude=runCatching{ObserverClock.parseLongitude(prefs.getString("observer_coordinates","")?:"")}.getOrNull();timeline.onObserverSetup={observerSettings()};timeline.onEdit={EventEditor(this,it).show()};timeline.onSameTime={list->chooseTied(list)};timeline.onStateChange={ui.removeCallbacks(savePending);ui.postDelayed(savePending,250)};root.add(timeline,-1,0,1f);setContentView(root);updateScaleLabel()};private fun updateScaleLabel(){scaleText.text=when(timeline.selectedScale){1->"MONTH";2->"YEAR";else->"DAY"}};fun save(event:TimelineEvent){store.save(event);timeline.setAll(store.all())};fun delete(event:TimelineEvent){store.delete(event.id);timeline.setAll(store.all())};private fun saveStateNow(){if(!::timeline.isInitialized)return;getSharedPreferences("viewport",MODE_PRIVATE).edit().putLong("center_second",timeline.center.second).putInt("center_nano",timeline.center.nano).putString("spp",timeline.secondsPerPixel.toString()).putFloat("horizontal",timeline.horizontalPan).putInt("scale",timeline.selectedScale).apply()};override fun onResume(){super.onResume();ui.removeCallbacks(nowRefresh);ui.postDelayed(nowRefresh,0L)};override fun onPause(){ui.removeCallbacks(nowRefresh);saveStateNow();super.onPause()};override fun onDestroy(){ui.removeCallbacks(nowRefresh);ui.removeCallbacks(savePending);stopGps();store.close();super.onDestroy()};private fun observerSettings(){val outer=column();outer.setPadding(dp(12),dp(10),dp(12),dp(10));outer.add(label("Longitude determines local mean solar time: 240 seconds per degree, east positive. This does not change any event timestamps.",14f));val field=field(getSharedPreferences("viewport",MODE_PRIVATE).getString("observer_coordinates","")?:"","Longitude, or latitude, longitude");outer.add(field,-1,dp(50));outer.add(action("GET COORDINATES FROM GPS"){acquireLocation{lat,lon,extra->field.setText("$lat, $lon");notifyTransfer(extra)}},-1,dp(48));val error=label("Tap the vertical time readout or long-press Now to edit this setting.",12f);outer.add(error);val buttons=row();var dlg:android.app.Dialog?=null;buttons.add(action("CANCEL"){dlg?.dismiss()},0,dp(50),1f);buttons.add(action("SAVE LONGITUDE"){val raw=field.text.toString().trim();val longitude=runCatching{ObserverClock.parseLongitude(raw)}.getOrElse{error.text=it.message?:"Invalid longitude";return@action};getSharedPreferences("viewport",MODE_PRIVATE).edit().putString("observer_coordinates",raw).apply();timeline.observerLongitude=longitude;dlg?.dismiss()},0,dp(50),2f);outer.add(buttons);dlg=modal("OBSERVER LONGITUDE",outer);dlg.show();dlg.window?.setLayout((resources.displayMetrics.widthPixels*0.95).toInt(),WindowManager.LayoutParams.WRAP_CONTENT)};private fun openEventSearch(){val visibleIds=timeline.visibleEvents.mapTo(HashSet()){it.id};EventSearch(this,store.all(),visibleIds){event->timeline.jumpToEvent(event)}.show()};private fun openBulkVisibility(){val rows=store.all().mapIndexed{index,event->TransferEntry(index,event.title,event.civil,event,VisibilityScale.description(event.maxScaleAmount,event.maxScaleUnit),false)};TransferSelection(this,rows,false,false,"SELECT EVENTS TO CONFIGURE","EDIT VISIBILITY"){selected->if(selected.isNotEmpty())configureBulkVisibility(selected) else notifyTransfer("No events selected")}.show()};private fun configureBulkVisibility(selected:List<TimelineEvent>){val outer=column();outer.setPadding(dp(10),dp(8),dp(10),dp(8));outer.add(label("Apply the same maximum visible timeline span to ${selected.size} events. Leave the amount empty to make them always visible.",14f));val amount=field("","1/3, 2^10, 1.5e-4; empty = always");outer.add(amount,-1,dp(48));var unit="DAY";val selector=action("DAYS"){};selector.setOnClickListener{choose("VISIBILITY UNITS",listOf("DAYS","MEAN SYNODIC MONTHS","MEAN SOLSTICE YEARS")){unit=listOf("DAY","MONTH","YEAR")[it];selector.text=listOf("DAYS","MEAN SYNODIC MONTHS","MEAN SOLSTICE YEARS")[it]}};outer.add(selector,-1,dp(48));val error=label("Exact fractions, powers and scientific notation are supported. Applies to the full viewport span.",12f);outer.add(error);val actions=row();var dlg:android.app.Dialog?=null;actions.add(action("CANCEL"){dlg?.dismiss()},0,dp(50),1f);actions.add(action("APPLY TO ${selected.size}"){val limit=runCatching{VisibilityScale.normalize(amount.text.toString(),unit)}.getOrElse{error.text=it.message?:"Invalid threshold";return@action};dlg?.dismiss();Thread{runCatching{store.saveBatch(selected.map{it.copy(maxScaleAmount=limit.first,maxScaleUnit=limit.second,updated=System.currentTimeMillis())})}.onSuccess{runOnUiThread{timeline.setAll(store.all());notifyTransfer("Updated visibility for ${selected.size} events")}}.onFailure{runOnUiThread{notifyTransfer("Could not update visibility: ${it.message}")}}}.start()},0,dp(50),2f);outer.add(actions);dlg=modal("BULK EVENT VISIBILITY",outer);dlg.show();dlg.window?.setLayout((resources.displayMetrics.widthPixels*0.95).toInt(),WindowManager.LayoutParams.WRAP_CONTENT)};private fun chooseTied(items:List<TimelineEvent>){val root=column();root.add(label("${items.size} events share ${items[0].moment.utc()}",12f));val list=ScrollView(this);val rows=column();var dialog:android.app.Dialog?=null;var page=0;lateinit var populate:()->Unit;val pager=row();val previous=action("PREVIOUS"){if(page>0){page--;populate()}};val next=action("NEXT"){if((page+1)*60<items.size){page++;populate()}};populate={rows.removeAllViews();for(event in items.drop(page*60).take(60))rows.add(action(event.title){dialog?.dismiss();EventEditor(this,event).show()},-1,dp(42));previous.text="PREVIOUS (${page+1})";next.text="NEXT (${(items.size+59)/60})"};pager.add(previous,0,dp(44),1f);pager.add(next,0,dp(44),1f);list.addView(rows);root.add(list,-1,dp(360));root.add(pager);populate();dialog=modal("EVENTS AT SAME INSTANT",root);dialog.show();dialog.window?.setLayout((resources.displayMetrics.widthPixels*0.94).toInt(),WindowManager.LayoutParams.WRAP_CONTENT)};private fun diagnostics(){val focus=timeline.focus();val report="Deep Timeline\nVersion: $APP_VERSION\nAndroid API: ${Build.VERSION.SDK_INT}\nDevice: ${Build.MANUFACTURER} ${Build.MODEL}\nEvents: ${timeline.events.size}\nVisible at current zoom: ${timeline.visibleEvents.size}\nMaximum viewport span: ${timeline.secondsPerPixel*timeline.height/86400.0} days\nObserver coordinates: ${getSharedPreferences("viewport",MODE_PRIVATE).getString("observer_coordinates", "Not set")}\nLongitudinal center: ${ObserverClock.display(timeline.center,timeline.observerLongitude)}\nCenter: ${timeline.center.utc()}\nNearest event: ${focus?.title?:"None"}\nScale preset: ${listOf("Day","Mean synodic month","Mean December-solstice year")[timeline.selectedScale]}\nSeconds per pixel: ${timeline.secondsPerPixel}\nHorizontal pan pixels: ${timeline.horizontalPan}\nAndroid font scale: ${resources.configuration.fontScale}\nEvent font pixels: ${timeline.labelFontPixels}\nEvent baseline gap pixels: ${timeline.labelLineGapPixels}\nFrame draw milliseconds: ${"%.3f".format(Locale.US,timeline.frameTime)}\nLabel layout milliseconds: ${"%.3f".format(Locale.US,timeline.layoutTime)}\nDevice timezone: ${ZoneId.systemDefault().id}\nGeographic timezone resolver: ${ZoneResolver.SOURCE}, offline automatic coordinate lookup\nLocation: $lastLocationStatus\nPermission: ${if(checkSelfPermission(Manifest.permission.ACCESS_FINE_LOCATION)==PackageManager.PERMISSION_GRANTED)"Granted" else "Not granted"}\nConnectivity: Offline only";val root=column();val scroll=ScrollView(this);val text=label(report,13f);text.setTextIsSelectable(true);scroll.addView(text);root.add(scroll,-1,dp(390));val buttons=row();var dialog:android.app.Dialog?=null;buttons.add(action("CLOSE"){dialog?.dismiss()},0,dp(48),1f);buttons.add(action("COPY TO CLIPBOARD"){val clip=getSystemService(Context.CLIPBOARD_SERVICE) as ClipboardManager;clip.setPrimaryClip(ClipData.newPlainText("Deep Timeline diagnostics",report));dialog?.dismiss()},0,dp(48),2f);root.add(buttons);dialog=modal("DIAGNOSTICS",root);dialog.show();dialog.window?.setLayout((resources.displayMetrics.widthPixels*0.96).toInt(),WindowManager.LayoutParams.WRAP_CONTENT)};fun acquireLocation(receiver:(String,String,String)->Unit){gpsCallback=receiver;if(checkSelfPermission(Manifest.permission.ACCESS_FINE_LOCATION)!=PackageManager.PERMISSION_GRANTED){requestPermissions(arrayOf(Manifest.permission.ACCESS_FINE_LOCATION,Manifest.permission.ACCESS_COARSE_LOCATION),911);return};startGps()};override fun onRequestPermissionsResult(requestCode:Int,permissions:Array<out String>,grantResults:IntArray){super.onRequestPermissionsResult(requestCode,permissions,grantResults);if(requestCode==911){if(checkSelfPermission(Manifest.permission.ACCESS_FINE_LOCATION)==PackageManager.PERMISSION_GRANTED)startGps()else lastLocationStatus="Location permission denied"}};private fun stopGps(){val lm=getSystemService(LOCATION_SERVICE) as LocationManager;activeListener?.let{try{lm.removeUpdates(it)}catch(_:Exception){}};activeListener=null;listenerTimeout?.let{ui.removeCallbacks(it)};listenerTimeout=null};private fun startGps(){stopGps();try{val lm=getSystemService(LOCATION_SERVICE) as LocationManager;val providers=listOf(LocationManager.GPS_PROVIDER,LocationManager.NETWORK_PROVIDER).filter{lm.isProviderEnabled(it)};if(providers.isEmpty()){lastLocationStatus="Location services are disabled";return};lastLocationStatus="Requesting a current coordinate fix";var received=false;val listener=object:LocationListener{override fun onLocationChanged(location:Location){if(received)return;received=true;deliver(location,false);stopGps()};override fun onProviderEnabled(provider:String){};override fun onProviderDisabled(provider:String){};override fun onStatusChanged(provider:String,status:Int,extras:Bundle?){}};activeListener=listener;for(provider in providers){lm.requestLocationUpdates(provider,0L,0f,listener,Looper.getMainLooper())};val timeout=Runnable{if(!received){received=true;stopGps();val cache=providers.mapNotNull{p->runCatching{lm.getLastKnownLocation(p)}.getOrNull()}.maxByOrNull{it.time};if(cache==null){lastLocationStatus="No location fix available";choose("GPS UNAVAILABLE",listOf("OK")){} }else{val age=((System.currentTimeMillis()-cache.time)/1000).coerceAtLeast(0);choose("NO CURRENT FIX — USE CACHED COORDINATES?",listOf("USE ${age}s-OLD FIX (±${cache.accuracy.toInt()}m)","CANCEL")){choice->if(choice==0)deliver(cache,true)}}}};listenerTimeout=timeout;ui.postDelayed(timeout,15000)}catch(e:Exception){lastLocationStatus="Location error: ${e.message}";stopGps()}};private fun deliver(location:Location,cached:Boolean){val age=((System.currentTimeMillis()-location.time)/1000).coerceAtLeast(0);val extra="${if(cached)"Cached" else "Current"} GPS fix: ${age}s old, ±${location.accuracy.toInt()} m";lastLocationStatus=extra;gpsCallback?.invoke(location.latitude.toString(),location.longitude.toString(),extra)}private fun notifyTransfer(message:String){Toast.makeText(this,message,Toast.LENGTH_LONG).show()};private fun openDangerZone(){choose("DANGER ZONE",listOf("OVERWRITE TIMELINE FROM JSON","RESTORE PREVIOUS OVERWRITE","CANCEL")){when(it){0->openImport(true);1->restorePrevious()}}};private fun openIcsImport(){val picker=Intent(Intent.ACTION_OPEN_DOCUMENT).apply{addCategory(Intent.CATEGORY_OPENABLE);type="*/*";putExtra(Intent.EXTRA_MIME_TYPES,arrayOf("text/calendar","application/ics","text/plain","application/octet-stream"))};startActivityForResult(picker,1205)};private fun openImport(overwrite:Boolean=false){val picker=Intent(Intent.ACTION_OPEN_DOCUMENT).apply{addCategory(Intent.CATEGORY_OPENABLE);type="*/*";putExtra(Intent.EXTRA_MIME_TYPES,arrayOf("application/json","text/json","text/plain","application/octet-stream"))};startActivityForResult(picker,if(overwrite)1204 else 1201)};private fun restorePrevious(){if(!OverwriteBackup.available(this)){notifyTransfer("No previous overwrite backup exists");return};Thread{runCatching{EventJson.parse(applicationContext,OverwriteBackup.read(applicationContext),emptyList())}.onSuccess{rows->runOnUiThread{reviewIncoming(rows,true)}}.onFailure{error->runOnUiThread{notifyTransfer("Backup could not be read: ${error.message}")}}}.start()};private fun reviewIncoming(rows:List<TransferEntry>,overwrite:Boolean){val checked=if(overwrite)rows.map{it.copy(defaultSelected=it.event!=null&&it.status!="DUPLICATE")} else rows;TransferSelection(this,checked,true,overwrite){selected->if(overwrite)confirmOverwrite(selected) else Thread{runCatching{store.saveBatch(selected)}.onSuccess{runOnUiThread{timeline.setAll(store.all());notifyTransfer("Imported ${selected.size} events")}}.onFailure{error->runOnUiThread{notifyTransfer("Import failed: ${error.message}")}}}.start()}.show()};private fun confirmOverwrite(selected:List<TimelineEvent>){val current=store.all();val result=runCatching{OverwriteRules.summarize(current.map{it.id},selected.map{it.id})}.getOrElse{notifyTransfer(it.message?:"Invalid overwrite selection");return};val outer=column();outer.setPadding(dp(14),dp(12),dp(14),dp(12));outer.add(label("DANGER: REPLACE ENTIRE TIMELINE",19f));outer.add(label("Currently stored: ${result.existing} events\nSelected from file: ${result.selected} events\nDeleted from existing timeline: ${result.removed} events\nExisting IDs retained: ${result.sharedIds}\nNew IDs: ${result.newIds}",15f));outer.add(label("Everything not checked will be deleted. Checked events replace stored versions even if their dates differ. A single pre-overwrite backup is saved privately on this device, and can be restored from DANGER ZONE. The next overwrite replaces that backup.",13f));outer.add(label("Type OVERWRITE to authorize replacement:",14f));val phrase=field("","OVERWRITE");outer.add(phrase,-1,dp(52));val buttons=row();var dialog:android.app.Dialog?=null;buttons.add(action("CANCEL"){dialog?.dismiss()},0,dp(50),1f);buttons.add(action("OVERWRITE"){if(phrase.text.toString()!="OVERWRITE"){notifyTransfer("Enter OVERWRITE exactly");return@action};dialog?.dismiss();Thread{runCatching{OverwriteBackup.save(applicationContext,store.all());store.replaceAll(selected)}.onSuccess{runOnUiThread{timeline.setAll(store.all());notifyTransfer("Timeline replaced: ${selected.size} events; previous timeline backed up")}}.onFailure{error->runOnUiThread{notifyTransfer("Overwrite failed: ${error.message}")}}}.start()},0,dp(50),1f);outer.add(buttons);dialog=modal("FINAL OVERWRITE CONFIRMATION",outer);dialog.show();dialog.window?.setLayout((resources.displayMetrics.widthPixels*0.96).toInt(),WindowManager.LayoutParams.WRAP_CONTENT)};private fun saveDocument(template:Boolean){val picker=Intent(Intent.ACTION_CREATE_DOCUMENT).apply{addCategory(Intent.CATEGORY_OPENABLE);type="application/json";putExtra(Intent.EXTRA_TITLE,if(template)"Deep_Timeline_Template_v20261111T141738Z.json" else "Deep_Timeline_Events_v20261111T141738Z.json")};startActivityForResult(picker,if(template)1203 else 1202)};override fun onActivityResult(requestCode:Int,resultCode:Int,data:Intent?){super.onActivityResult(requestCode,resultCode,data);if(requestCode !in 1201..1205)return;val uri=if(resultCode==RESULT_OK)data?.data else null;if(uri==null){if(requestCode==1202)outgoing=null;return};if(requestCode==1201||requestCode==1204||requestCode==1205){val overwrite=requestCode==1204;val existing=if(overwrite)emptyList() else store.all();Thread{runCatching{val bytes=ByteArrayOutputStream();contentResolver.openInputStream(uri)?.use{source->val block=ByteArray(32768);while(true){val n=source.read(block);if(n<0)break;bytes.write(block,0,n);require(bytes.size()<=67108864){"${if(requestCode==1205)"ICS" else "JSON"} file exceeds the 64 MiB import limit"}}}?:throw IllegalArgumentException("Could not open JSON file");if(requestCode==1205)IcsTransfer.preview(applicationContext,bytes.toString("UTF-8"),existing) else EventJson.parse(applicationContext,bytes.toString("UTF-8"),existing)}.onSuccess{rows->runOnUiThread{reviewIncoming(rows,overwrite)}}.onFailure{error->runOnUiThread{notifyTransfer("Invalid ${if(requestCode==1205)"ICS" else "JSON"}: ${error.message}")}}}.start()}else{val chosen=if(requestCode==1203)emptyList() else outgoing;outgoing=null;if(chosen==null)return;Thread{runCatching{val content=if(requestCode==1203)EventJson.template() else EventJson.export(chosen);contentResolver.openOutputStream(uri,"wt")?.use{it.write(content.toByteArray(Charsets.UTF_8));it.flush()}?:throw IllegalArgumentException("Could not write selected document")}.onSuccess{runOnUiThread{notifyTransfer(if(requestCode==1203)"Template saved" else "Exported ${chosen.size} events")}}.onFailure{error->runOnUiThread{notifyTransfer("Export failed: ${error.message}")}}}.start()}}}